    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) {
            return;
        }

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";

        if (Array.isArray(rawValueFromCharacterData) && rawValueFromCharacterData.length > 1 && typeof rawValueFromCharacterData[1] === 'string') {
            descriptionText = rawValueFromCharacterData[1];
        }

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }

        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if(color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-highlight)';
            }
        }
    }

    function updateBooleanDisplay(mainId, descId, characterData, dataPath, trueText, falseText) {
        const boolEl = document.getElementById(mainId);
        const boolDescEl = document.getElementById(descId);
        const rawValue = SafeGetValue(characterData, dataPath, false);
        let displayVal = (String(rawValue).toLowerCase() === 'true' || rawValue === true);

        if (boolEl) {
            boolEl.innerText = displayVal ? trueText : falseText;
            boolEl.className = 'value-main ' + (displayVal ? 'status-true' : 'status-false');
        }
        if (boolDescEl) {
            let descText = "";
            try {
                const pathArray = dataPath.split('.');
                let current = characterData;
                for (const key of pathArray) { current = current[key]; }
                if (Array.isArray(current) && current.length > 1 && typeof current[1] === 'string') {
                    descText = `(${current[1]})`;
                }
            } catch (e) { /* do nothing */ }
            boolDescEl.innerText = descText;
        }
    }


    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            const characterKey = "木野洋子";

            if (characterData.hasOwnProperty(characterKey)) {
                updateProgressBar('kino-yoko-affection-bar', 'kino-yoko-affection', 'kino-yoko-affection-desc', SafeGetValue(characterData, `${characterKey}.好感度`), 0, 100, 'var(--progress-affection)');
                updateProgressBar('kino-yoko-shakoudo-bar', 'kino-yoko-shakoudo', 'kino-yoko-shakoudo-desc', SafeGetValue(characterData, `${characterKey}.社恐度`), 0, 100, 'var(--progress-shakoudo)');
                updateProgressBar('kino-yoko-popularity-bar', 'kino-yoko-popularity', 'kino-yoko-popularity-desc', SafeGetValue(characterData, `${characterKey}.人气值`), 0, 99, 'var(--progress-popularity)');

                updateBooleanDisplay('kino-yoko-reveal-rinko', 'kino-yoko-reveal-rinko-desc', characterData, `${characterKey}.身份揭露（音无凛子）`, '已揭露', '未揭露');
                updateBooleanDisplay('kino-yoko-reveal-kaoru', 'kino-yoko-reveal-kaoru-desc', characterData, `${characterKey}.身份揭露（浅山薰）`, '已揭露', '未揭露');
                updateBooleanDisplay('kino-yoko-public-rinko', 'kino-yoko-public-rinko-desc', characterData, `${characterKey}.身份公开（音无凛子）`, '已公开', '未公开');

            } else {
                 document.getElementById('kino-yoko-affection').innerText = 'N/A';
                 document.getElementById('kino-yoko-shakoudo').innerText = 'N/A';
                 document.getElementById('kino-yoko-popularity').innerText = 'N/A';
                 document.getElementById('kino-yoko-reveal-rinko').innerText = 'N/A';
                 document.getElementById('kino-yoko-reveal-kaoru').innerText = 'N/A';
                 document.getElementById('kino-yoko-public-rinko').innerText = 'N/A';

                 const descIds = ['kino-yoko-affection-desc', 'kino-yoko-shakoudo-desc', 'kino-yoko-popularity-desc', 'kino-yoko-reveal-rinko-desc', 'kino-yoko-reveal-kaoru-desc', 'kino-yoko-public-rinko-desc'];
                 descIds.forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.innerText = '(角色数据缺失)';
                 });

                 const barIds = ['kino-yoko-affection-bar', 'kino-yoko-shakoudo-bar', 'kino-yoko-popularity-bar'];
                 barIds.forEach(id => {
                    const bar = document.getElementById(id);
                    if (bar) bar.style.width = '0%';
                 });
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';

        if(!isExpanded && element.parentElement.classList.contains('section:last-child')) {
            element.style.borderBottom = "none";
        } else if (element.parentElement.classList.contains('section:last-child')) {
             element.style.borderBottom = "1px solid var(--border-soft)";
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
